<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import ImgbedUploadPanel from './ImgbedUploadPanel.vue';
import type { ImgbedUploadBridge } from '../services/imgbedUploadBridge';
import type { RemoteGalleryImage, RemoteGalleryPayload } from '../../char_info_shared/remoteGallery';
import { refreshRemoteGallery } from '../../char_info_viewer/services/remoteGalleryService';
import {
  createImgbedBridge,
  displayImgbedMediaTitle,
  IMG_BED_CONNECTION_TIMEOUT_MS,
  IMG_BED_ORIGIN,
  parseImgbedGalleryUrl,
} from '../services/imgbedBridge';

import {
  normalizePortraitMediaUrlForBrowser,
  type NormalizedPortraitMedia,
  type PortraitMediaKind,
} from '../../char_info_viewer/services/imageUrl';
import {
  createMediaSourceTimeout,
  nextMediaSourceIndex,
  type MediaSourceTimeout,
} from '../../char_info_viewer/services/mediaSourceFallback';
import {
  firstStaticImage,
  firstViewerImage,
  isViewerVisible,
  preferredStaticImageUrl,
  setMainViewerImage,
  setViewerVisibility,
  type EditableGalleryImage,
} from '../galleryEditor';

const props = withDefaults(
  defineProps<{
    gallery: EditableGalleryImage[];
    avatarUrl: string;
    coverUrl: string;
    remoteGalleryUrl: string;
    characterName: string;
    debugEnabled: boolean;
    flashMode?: boolean;
    imgbedBridge?: ReturnType<typeof createImgbedBridge>;
    imgbedUploadBridge?: ImgbedUploadBridge;
  }>(),
  {
    flashMode: false,
    imgbedBridge: undefined,
    imgbedUploadBridge: undefined,
  },
);

const sourceMode = ref<'links' | 'upload'>(props.remoteGalleryUrl.trim() ? 'upload' : 'links');
const uploadPanel = ref<InstanceType<typeof ImgbedUploadPanel> | null>(null);
defineExpose({
  saveUploads: () => uploadPanel.value?.save(),
  hasPendingUploadMedia: computed(() => uploadPanel.value?.hasPendingMedia ?? false),
});

const emit = defineEmits<{
  'update:gallery': [value: EditableGalleryImage[]];
  'update:avatarUrl': [value: string];
  'update:coverUrl': [value: string];
  'update:remoteGalleryUrl': [value: string];
  previous: [];
  next: [];
}>();

const gallery = computed({
  get: () => props.gallery,
  set: value => emit('update:gallery', value),
});

const avatarSelection = ref('');
const coverSelection = ref('');
const batchMode = ref(false);
const selectedIds = ref<number[]>([]);
const batchMessage = ref('');
const imgbedAlbumId = computed(() => parseImgbedGalleryUrl(props.remoteGalleryUrl));
const imgbedBusy = ref(false);
const imgbedStatus = ref('');
const imgbedPreview = ref<RemoteGalleryPayload | null>(null);
type RemoteImageOption = {
  index: number;
  label: string;
  preview: string;
  avatarUrl: string;
  coverUrl: string;
};
function sameRemoteImage(left: string, right: string): boolean {
  if (!left || !right) return false;
  try {
    const a = new URL(left);
    const b = new URL(right);
    return a.origin === b.origin && a.pathname === b.pathname;
  } catch {
    return left === right;
  }
}
function remoteVariantUrl(image: RemoteGalleryImage, variant: 'avatar' | 'library'): string {
  const url =
    image.thumbnail ||
    image.sources.find(source => normalizePortraitMediaUrlForBrowser(source)?.kind === 'image') ||
    '';
  if (!url) return '';
  try {
    const parsed = new URL(url);
    if (parsed.origin === new URL(props.remoteGalleryUrl).origin && parsed.pathname.startsWith('/thumb/')) {
      parsed.searchParams.set('variant', variant);
      return parsed.toString();
    }
  } catch {
    // Unsupported external links use their existing thumbnail URL.
  }
  return url;
}
const remoteOptions = computed<RemoteImageOption[]>(() =>
  (imgbedPreview.value?.gallery ?? []).flatMap((image, index) => {
    const preview =
      image.thumbnail ||
      image.sources.find(source => normalizePortraitMediaUrlForBrowser(source)?.kind === 'image') ||
      '';
    if (!preview) return [];
    return [
      {
        index,
        label:
          displayImgbedMediaTitle(image.title, index) === `图片 ${index + 1}`
            ? `图片 ${index + 1}`
            : `图片 ${index + 1} · ${image.title}`,
        preview,
        avatarUrl: remoteVariantUrl(image, 'avatar'),
        coverUrl: remoteVariantUrl(image, 'library'),
      },
    ];
  }),
);
function remoteChoice(currentUrl: string, defaultUrl: string): string {
  if (!currentUrl || currentUrl === defaultUrl) return 'default';
  const found = remoteOptions.value.find(item => sameRemoteImage(item.preview, currentUrl));
  return found ? String(found.index) : 'existing';
}
const currentRemoteAvatarChoice = computed(() =>
  remoteChoice(props.avatarUrl, imgbedPreview.value?.avatarThumbnail ?? ''),
);
const currentRemoteCoverChoice = computed(() =>
  remoteChoice(props.coverUrl, imgbedPreview.value?.libraryThumbnail ?? ''),
);
const remoteMainPortraitLabel = computed(() => {
  const images = imgbedPreview.value?.gallery ?? [];
  const index = images.findIndex(image => image.viewerVisible !== false);
  return index < 0 ? '暂无主立绘' : displayImgbedMediaTitle(images[index].title, index);
});
function onRemoteAvatarChange(event: Event) {
  const chosen = (event.target as HTMLSelectElement).value;
  if (chosen === 'existing') return;
  const option = remoteOptions.value.find(item => String(item.index) === chosen);
  emit('update:avatarUrl', option?.avatarUrl || imgbedPreview.value?.avatarThumbnail || '');
}
function onRemoteCoverChange(event: Event) {
  const chosen = (event.target as HTMLSelectElement).value;
  if (chosen === 'existing') return;
  const option = remoteOptions.value.find(item => String(item.index) === chosen);
  emit('update:coverUrl', option?.coverUrl || imgbedPreview.value?.libraryThumbnail || '');
}
function applyImgbedPreview(payload: RemoteGalleryPayload) {
  const previous = imgbedPreview.value;
  function refreshedChoice(
    current: string,
    oldDefault: string,
    newDefault: string,
    variant: 'avatar' | 'library',
  ): string {
    const currentUrl = current.trim();
    if (!currentUrl || (oldDefault && currentUrl === oldDefault)) return newDefault || currentUrl;
    const matches = (pack: RemoteGalleryPayload) =>
      pack.gallery.find(image => sameRemoteImage(image.thumbnail || image.sources[0] || '', currentUrl));
    const updated = matches(payload);
    if (updated) return remoteVariantUrl(updated, variant);
    if (previous && matches(previous)) return newDefault;
    return currentUrl;
  }
  imgbedPreview.value = payload;
  const avatarUrl = refreshedChoice(
    props.avatarUrl,
    previous?.avatarThumbnail || '',
    payload.avatarThumbnail || '',
    'avatar',
  );
  const coverUrl = refreshedChoice(
    props.coverUrl,
    previous?.libraryThumbnail || '',
    payload.libraryThumbnail || '',
    'library',
  );
  if (avatarUrl !== props.avatarUrl) emit('update:avatarUrl', avatarUrl);
  if (coverUrl !== props.coverUrl) emit('update:coverUrl', coverUrl);
}
const pendingImgbedSelection = ref<{ url: string; payload: RemoteGalleryPayload } | null>(null);
let imgbedOperation = 0;
let imgbedAbort: AbortController | null = null;
let emittedRemoteUrl: string | null = null;

function cancelImgbedOperation() {
  imgbedOperation += 1;
  props.imgbedBridge?.cancel();
  imgbedAbort?.abort();
  imgbedAbort = null;
  imgbedBusy.value = false;
  pendingImgbedSelection.value = null;
}

watch(
  () => props.characterName,
  () => {
    cancelImgbedOperation();
    imgbedPreview.value = null;
    imgbedStatus.value = '';
  },
  { flush: 'sync' },
);
watch(
  () => props.remoteGalleryUrl,
  value => {
    if (value === emittedRemoteUrl) {
      emittedRemoteUrl = null;
      return;
    }
    emittedRemoteUrl = null;
    cancelImgbedOperation();
    imgbedPreview.value = null;
    imgbedStatus.value = '';
  },
  { flush: 'sync' },
);

function updateRemoteUrl(value: string) {
  const sameAlbum = value === props.remoteGalleryUrl && !!parseImgbedGalleryUrl(value);
  emittedRemoteUrl = sameAlbum ? null : value;
  emit('update:remoteGalleryUrl', value);
  // The uploader also emits after saving an existing album, when its URL is unchanged.
  if (sameAlbum) {
    void nextTick().then(() => {
      if (!uploadPanel.value?.hasUnsavedChanges) void refreshImgbed();
    });
  }
}

function onRemoteGalleryInput(event: Event) {
  cancelImgbedOperation();
  imgbedPreview.value = null;
  imgbedStatus.value = '';
  emit('update:remoteGalleryUrl', (event.target as HTMLInputElement).value);
}

async function loadImgbed(url: string, albumId: string, operation: number) {
  imgbedAbort = new AbortController();
  const payload = await refreshRemoteGallery(url, imgbedAbort.signal, candidate => {
    if (parseImgbedGalleryUrl(url) !== albumId || candidate.packId !== albumId || candidate.profileId !== albumId) {
      throw new Error('图库身份与所选相册不一致。');
    }
  });
  if (operation !== imgbedOperation) return null;
  return payload;
}

async function selectImgbed(albumId?: string) {
  cancelImgbedOperation();
  const operation = imgbedOperation;
  if (!props.imgbedBridge) {
    imgbedStatus.value = '无法打开 ImgBed，请在下方粘贴 ImgBed 公开图库 API URL。';
    return;
  }
  imgbedBusy.value = true;
  imgbedStatus.value = `请在 ${IMG_BED_CONNECTION_TIMEOUT_MS / 60_000} 分钟内在 ImgBed 完成登录并选择图库；可随时取消操作。`;
  try {
    const selected = await props.imgbedBridge.select(albumId);
    if (operation !== imgbedOperation) return;
    imgbedStatus.value = '正在验证图库…';
    const payload = await loadImgbed(selected.remoteGalleryUrl, selected.albumId, operation);
    if (!payload) return;
    if (payload.characterName !== props.characterName.trim()) {
      pendingImgbedSelection.value = { url: selected.remoteGalleryUrl, payload };
      imgbedStatus.value = '请确认角色姓名不同的图库。';
    } else {
      updateRemoteUrl(selected.remoteGalleryUrl);
      applyImgbedPreview(payload);
      imgbedStatus.value = '';
    }
  } catch (error) {
    if (operation !== imgbedOperation) return;
    const code = (error as { code?: string }).code;
    if (code === 'cancelled') {
      imgbedStatus.value = '已取消选择图库；原有图库设置保持不变。';
    } else if (code === 'closed') {
      imgbedStatus.value = 'ImgBed 窗口已关闭或连接已中断。请重新连接，或在下方粘贴 ImgBed 公开图库 API URL。';
    } else if (code === 'timeout') {
      imgbedStatus.value = `连接已超过 ${IMG_BED_CONNECTION_TIMEOUT_MS / 60_000} 分钟。请重新连接，或在下方粘贴 ImgBed 公开图库 API URL。`;
    } else if (code === 'blocked') {
      imgbedStatus.value = '弹窗被浏览器拦截。请允许弹窗，或在下方粘贴 ImgBed 公开图库 API URL。';
    } else if (code === 'unsupported') {
      imgbedStatus.value = '浏览器无法建立或保持图库连接。请在下方粘贴 ImgBed 公开图库 API URL。';
    } else {
      imgbedStatus.value = '连接或验证图库失败，请重试或在下方粘贴 ImgBed 公开图库 API URL。';
    }
  } finally {
    if (operation === imgbedOperation) imgbedBusy.value = false;
  }
}

function confirmImgbedSelection() {
  const selection = pendingImgbedSelection.value;
  if (!selection) return;
  updateRemoteUrl(selection.url);
  applyImgbedPreview(selection.payload);
  pendingImgbedSelection.value = null;
  imgbedStatus.value = '';
}

function cancelImgbedSelection() {
  cancelImgbedOperation();
  imgbedPreview.value = null;
  imgbedStatus.value = '已取消图库操作；原有图库设置保持不变。';
}

async function refreshImgbed() {
  const url = props.remoteGalleryUrl;
  const albumId = imgbedAlbumId.value;
  if (!albumId) return;
  if (uploadPanel.value?.hasUnsavedChanges) {
    imgbedStatus.value = '请先完成或取消待处理的图库操作，再刷新。';
    return;
  }
  cancelImgbedOperation();
  const operation = imgbedOperation;
  imgbedBusy.value = true;
  imgbedStatus.value = '正在更新图库…';
  try {
    const payload = await loadImgbed(url, albumId, operation);
    if (!payload || operation !== imgbedOperation) return;
    await uploadPanel.value?.reload?.();
    if (operation !== imgbedOperation) return;
    applyImgbedPreview(payload);
    imgbedStatus.value = `已更新 · ${payload.gallery.length} 张图片或视频`;
  } catch (error) {
    if (operation === imgbedOperation) {
      imgbedStatus.value = `刷新失败：${error instanceof Error ? error.message : String(error)}`;
    }
  } finally {
    if (operation === imgbedOperation) imgbedBusy.value = false;
  }
}
watch(
  () => [props.remoteGalleryUrl, sourceMode.value],
  ([url, mode]) => {
    if (!props.flashMode && mode === 'upload' && parseImgbedGalleryUrl(url) && !imgbedPreview.value) {
      void refreshImgbed();
    }
  },
  { immediate: true, flush: 'post' },
);

function disconnectImgbed() {
  cancelImgbedOperation();
  updateRemoteUrl('');
  imgbedPreview.value = null;
  imgbedStatus.value = '已解除绑定；ImgBed 网站的图片仍然保留。';
}

const staticImages = computed(() => gallery.value.filter(image => !!preferredStaticImageUrl(image)));
const mainViewerImageId = computed(() => firstViewerImage(gallery.value)?.id ?? null);
const avatarImageId = computed(() => parseGallerySelectionId(avatarSelection.value));
const coverImageId = computed(() => parseGallerySelectionId(coverSelection.value));

function indexForImage(image: EditableGalleryImage): number {
  return gallery.value.findIndex(candidate => candidate.id === image.id);
}

function parseGallerySelectionId(value: string): number | null {
  if (!value.startsWith('gallery:')) return null;
  const id = Number(value.slice('gallery:'.length));
  return Number.isFinite(id) ? id : null;
}

function syncRoleSelections() {
  const avatarUrl = props.avatarUrl.trim();
  const avatarMatch = gallery.value.find(image => preferredStaticImageUrl(image) === avatarUrl);
  const avatarMedia = avatarUrl ? normalizePortraitMediaUrlForBrowser(avatarUrl) : null;
  if (avatarMedia?.kind === 'video') {
    const fallback = firstStaticImage(gallery.value);
    avatarSelection.value = fallback ? `gallery:${fallback.id}` : '';
    emit('update:avatarUrl', preferredStaticImageUrl(fallback));
  } else {
    avatarSelection.value = avatarMatch ? `gallery:${avatarMatch.id}` : avatarUrl ? 'custom' : '';
  }

  const coverMatch = gallery.value.find(image => preferredStaticImageUrl(image) === props.coverUrl.trim());
  coverSelection.value = coverMatch ? `gallery:${coverMatch.id}` : '';

  if (props.flashMode) {
    const fallback = firstStaticImage(gallery.value);
    const fallbackUrl = preferredStaticImageUrl(fallback);
    if (fallback && fallbackUrl && !props.avatarUrl.trim()) {
      avatarSelection.value = `gallery:${fallback.id}`;
      emit('update:avatarUrl', fallbackUrl);
    }
    if (fallback && fallbackUrl && !props.coverUrl.trim()) {
      coverSelection.value = `gallery:${fallback.id}`;
      emit('update:coverUrl', fallbackUrl);
    }
  }
}

watch(() => [props.avatarUrl, props.coverUrl, gallery.value.length], syncRoleSelections, { immediate: true });

function onMainPortraitChange(event: Event) {
  const id = Number((event.target as HTMLSelectElement).value);
  if (!Number.isFinite(id)) return;
  setMainViewerImage(gallery.value, id);
  batchMessage.value = '';
}

function onAvatarSelectionChange(event: Event) {
  const value = (event.target as HTMLSelectElement).value;
  avatarSelection.value = value;
  if (value === 'custom') {
    if (gallery.value.some(image => preferredStaticImageUrl(image) === props.avatarUrl.trim()))
      emit('update:avatarUrl', '');
    return;
  }
  const id = parseGallerySelectionId(value);
  const image = id === null ? null : (gallery.value.find(candidate => candidate.id === id) ?? null);
  emit('update:avatarUrl', preferredStaticImageUrl(image));
}

function onCoverSelectionChange(event: Event) {
  const value = (event.target as HTMLSelectElement).value;
  coverSelection.value = value;
  const id = parseGallerySelectionId(value);
  const image = id === null ? null : (gallery.value.find(candidate => candidate.id === id) ?? null);
  emit('update:coverUrl', preferredStaticImageUrl(image));
}

function syncRoleUrlsForImage(image: EditableGalleryImage) {
  const url = preferredStaticImageUrl(image);
  if (props.flashMode && url) {
    if (!props.avatarUrl.trim()) {
      avatarSelection.value = `gallery:${image.id}`;
      emit('update:avatarUrl', url);
    }
    if (!props.coverUrl.trim()) {
      coverSelection.value = `gallery:${image.id}`;
      emit('update:coverUrl', url);
    }
  }
  if (avatarImageId.value === image.id) {
    emit('update:avatarUrl', url);
    if (!url) avatarSelection.value = '';
  }
  if (coverImageId.value === image.id) {
    emit('update:coverUrl', url);
    if (!url) coverSelection.value = '';
  }
}

function toggleBatchMode() {
  batchMode.value = !batchMode.value;
  selectedIds.value = [];
  batchMessage.value = '';
}

function toggleSelection(imageId: number) {
  selectedIds.value = selectedIds.value.includes(imageId)
    ? selectedIds.value.filter(id => id !== imageId)
    : [...selectedIds.value, imageId];
  batchMessage.value = '';
}

function selectAll() {
  selectedIds.value = gallery.value.map(image => image.id);
  batchMessage.value = '';
}

function clearSelection() {
  selectedIds.value = [];
  batchMessage.value = '';
}

function applyBatchVisibility(visible: boolean) {
  if (!selectedIds.value.length) return;
  if (!setViewerVisibility(gallery.value, selectedIds.value, visible)) {
    batchMessage.value = '至少要保留一张角色卡主立绘；请少选一张后再设为仅相册。';
    return;
  }
  batchMessage.value = visible ? '已设为显示于角色卡。' : '已设为仅相册。';
}

function nextImageId(): number {
  return Math.max(0, ...gallery.value.map(image => image.id)) + 1;
}

function addImage() {
  const number = gallery.value.length + 1;
  gallery.value.push({
    id: nextImageId(),
    title: number === 1 ? '主立绘' : `备用立绘 ${number}`,
    sources: [''],
    previewSourceIndex: 0,
  });
}

function removeImage(index: number) {
  if (gallery.value.length <= 1) return;
  const [removed] = gallery.value.splice(index, 1);
  selectedIds.value = selectedIds.value.filter(id => id !== removed.id);

  if (avatarImageId.value === removed.id) {
    const fallback = firstStaticImage(gallery.value);
    avatarSelection.value = fallback ? `gallery:${fallback.id}` : '';
    emit('update:avatarUrl', preferredStaticImageUrl(fallback));
  }
  if (coverImageId.value === removed.id) {
    coverSelection.value = '';
    emit('update:coverUrl', '');
  }
}

function moveImage(index: number, offset: -1 | 1) {
  const targetIndex = index + offset;
  if (targetIndex < 0 || targetIndex >= gallery.value.length) return;
  const [image] = gallery.value.splice(index, 1);
  gallery.value.splice(targetIndex, 0, image);
}

function addImageSource(image: EditableGalleryImage) {
  image.sources.push('');
}

function onGallerySourceInput(image: EditableGalleryImage) {
  image.previewSourceIndex = 0;
  syncRoleUrlsForImage(image);
}

function removeImageSource(image: EditableGalleryImage, sourceIndex: number) {
  if (image.sources.length <= 1) return;
  image.sources.splice(sourceIndex, 1);
  image.previewSourceIndex = 0;
  syncRoleUrlsForImage(image);
}

function moveImageSource(image: EditableGalleryImage, sourceIndex: number, offset: -1 | 1) {
  const targetIndex = sourceIndex + offset;
  if (targetIndex < 0 || targetIndex >= image.sources.length) return;
  const [source] = image.sources.splice(sourceIndex, 1);
  image.sources.splice(targetIndex, 0, source);
  image.previewSourceIndex = 0;
  syncRoleUrlsForImage(image);
}

function resolveGalleryPreviewSources(image: EditableGalleryImage): NormalizedPortraitMedia[] {
  return image.sources.reduce<NormalizedPortraitMedia[]>((sources, value) => {
    const media = normalizePortraitMediaUrlForBrowser(value);
    if (media && !sources.some(source => source.url === media.url)) sources.push(media);
    return sources;
  }, []);
}

function resolveGalleryPreviewMedia(image: EditableGalleryImage): NormalizedPortraitMedia | null {
  const sources = resolveGalleryPreviewSources(image);
  return sources[Math.min(image.previewSourceIndex, Math.max(0, sources.length - 1))] ?? null;
}

function resolveGalleryPreviewUrl(image: EditableGalleryImage): string {
  return resolveGalleryPreviewMedia(image)?.url ?? '';
}

function galleryPreviewMediaKind(image: EditableGalleryImage): PortraitMediaKind | null {
  return resolveGalleryPreviewMedia(image)?.kind ?? null;
}

function debugGalleryPreview(image: EditableGalleryImage, event: string, details: Record<string, unknown> = {}) {
  if (!props.debugEnabled) return;
  const sources = resolveGalleryPreviewSources(image);
  console.info('[CharInfo][ImageFallback][ProfileEditor]', {
    event,
    character: props.characterName,
    imageTitle: image.title,
    sourceIndex: image.previewSourceIndex,
    url: sources[image.previewSourceIndex]?.url ?? '',
    ...details,
  });
}

const galleryPreviewElements = new Map<number, HTMLImageElement | HTMLVideoElement>();
const galleryPreviewTimeouts = new Map<number, MediaSourceTimeout>();
const visibleGalleryPreviewIds = new Set<number>();
const activeGalleryVideoId = ref<number | null>(null);
let galleryVideoHoverTimer: number | null = null;
let galleryPreviewObserver: IntersectionObserver | null = null;

function galleryPreviewTimeoutFor(image: EditableGalleryImage): MediaSourceTimeout {
  let timeout = galleryPreviewTimeouts.get(image.id);
  if (timeout) return timeout;
  timeout = createMediaSourceTimeout(() => {
    if (!visibleGalleryPreviewIds.has(image.id)) return;
    debugGalleryPreview(image, 'timeout');
    advanceGalleryPreviewSource(image, 'timeout');
  });
  galleryPreviewTimeouts.set(image.id, timeout);
  return timeout;
}

function clearGalleryPreviewTimeout(image: EditableGalleryImage) {
  galleryPreviewTimeouts.get(image.id)?.clear();
}

function pauseGalleryVideo(imageId: number) {
  const element = galleryPreviewElements.get(imageId);
  if (element instanceof HTMLVideoElement) element.pause();
  if (activeGalleryVideoId.value === imageId) activeGalleryVideoId.value = null;
}

function pauseOtherGalleryVideos(exceptImageId: number) {
  galleryPreviewElements.forEach((element, imageId) => {
    if (imageId !== exceptImageId && element instanceof HTMLVideoElement) element.pause();
  });
  if (activeGalleryVideoId.value !== exceptImageId) activeGalleryVideoId.value = null;
}

function playGalleryVideo(image: EditableGalleryImage) {
  const element = galleryPreviewElements.get(image.id);
  if (!(element instanceof HTMLVideoElement)) return;
  if (galleryPreviewObserver && !visibleGalleryPreviewIds.has(image.id)) return;
  pauseOtherGalleryVideos(image.id);
  activeGalleryVideoId.value = image.id;
  void element.play().catch(() => {
    if (activeGalleryVideoId.value === image.id) activeGalleryVideoId.value = null;
  });
}

function toggleGalleryVideo(image: EditableGalleryImage) {
  const element = galleryPreviewElements.get(image.id);
  if (!(element instanceof HTMLVideoElement)) return;
  if (!element.paused && activeGalleryVideoId.value === image.id) pauseGalleryVideo(image.id);
  else playGalleryVideo(image);
}

function clearGalleryVideoHoverTimer() {
  if (galleryVideoHoverTimer === null) return;
  window.clearTimeout(galleryVideoHoverTimer);
  galleryVideoHoverTimer = null;
}

function onGalleryVideoPointerEnter(image: EditableGalleryImage, event: PointerEvent) {
  if (event.pointerType !== 'mouse') return;
  clearGalleryVideoHoverTimer();
  galleryVideoHoverTimer = window.setTimeout(() => {
    galleryVideoHoverTimer = null;
    playGalleryVideo(image);
  }, 150);
}

function onGalleryVideoPointerLeave(image: EditableGalleryImage, event: PointerEvent) {
  if (event.pointerType !== 'mouse') return;
  clearGalleryVideoHoverTimer();
  pauseGalleryVideo(image.id);
}

function onGalleryVideoPointerUp(image: EditableGalleryImage, event: PointerEvent) {
  clearGalleryVideoHoverTimer();
  if (event.pointerType !== 'mouse') toggleGalleryVideo(image);
}

function advanceGalleryPreviewSource(image: EditableGalleryImage, reason: 'error' | 'timeout') {
  clearGalleryPreviewTimeout(image);
  const sources = resolveGalleryPreviewSources(image);
  const fromIndex = image.previewSourceIndex;
  const nextIndex = nextMediaSourceIndex(fromIndex, sources.length);
  if (nextIndex !== null) {
    image.previewSourceIndex = nextIndex;
    debugGalleryPreview(image, 'fallback', { reason, fromIndex, toIndex: nextIndex });
    debugGalleryPreview(image, 'try');
    return;
  }
  debugGalleryPreview(image, 'all_failed', { reason, fromIndex });
}

function onGalleryPreviewLoad(image: EditableGalleryImage) {
  clearGalleryPreviewTimeout(image);
  debugGalleryPreview(image, 'loaded');
}

function onGalleryPreviewError(image: EditableGalleryImage) {
  pauseGalleryVideo(image.id);
  debugGalleryPreview(image, 'error');
  advanceGalleryPreviewSource(image, 'error');
}

function setGalleryPreviewElement(image: EditableGalleryImage, element: unknown) {
  const previous = galleryPreviewElements.get(image.id);
  if (previous) {
    galleryPreviewObserver?.unobserve(previous);
    pauseGalleryVideo(image.id);
  }

  if (!(element instanceof HTMLImageElement) && !(element instanceof HTMLVideoElement)) {
    galleryPreviewElements.delete(image.id);
    visibleGalleryPreviewIds.delete(image.id);
    clearGalleryPreviewTimeout(image);
    return;
  }

  galleryPreviewElements.set(image.id, element);
  if (galleryPreviewObserver) {
    galleryPreviewObserver.observe(element);
    return;
  }

  visibleGalleryPreviewIds.add(image.id);
  debugGalleryPreview(image, 'try');
  galleryPreviewTimeoutFor(image).arm();
}

function initializeGalleryPreviewObserver() {
  if (typeof IntersectionObserver === 'undefined') return;
  galleryPreviewObserver = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      const element = entry.target as HTMLImageElement | HTMLVideoElement;
      const imageId = Number(element.dataset.galleryImageId);
      const image = gallery.value.find(candidate => candidate.id === imageId);
      if (!image) return;
      if (entry.isIntersecting) {
        visibleGalleryPreviewIds.add(imageId);
        debugGalleryPreview(image, 'try');
        galleryPreviewTimeoutFor(image).arm();
      } else {
        visibleGalleryPreviewIds.delete(imageId);
        pauseGalleryVideo(imageId);
        clearGalleryPreviewTimeout(image);
      }
    });
  });
  galleryPreviewElements.forEach(element => galleryPreviewObserver?.observe(element));
}

onMounted(initializeGalleryPreviewObserver);

onBeforeUnmount(() => {
  cancelImgbedOperation();
  clearGalleryVideoHoverTimer();
  galleryPreviewObserver?.disconnect();
  galleryPreviewObserver = null;
  galleryPreviewElements.forEach((element, imageId) => {
    if (element instanceof HTMLVideoElement) pauseGalleryVideo(imageId);
  });
  galleryPreviewTimeouts.forEach(timeout => timeout.dispose());
  galleryPreviewTimeouts.clear();
  galleryPreviewElements.clear();
  visibleGalleryPreviewIds.clear();
});
</script>

